const sizeForm=document.querySelector('#size-form');
if(sizeForm){sizeForm.addEventListener('submit',ev=>{ev.preventDefault();const vals=['item-w','item-h','case-w','case-h'].map(id=>Number(document.getElementById(id).value));const result=document.querySelector('#size-result');if(vals.some(v=>!Number.isFinite(v)||v<=0||v>2000)){result.textContent='0より大きく、2000以下の寸法を入力してください。';return;}const [w,h,cw,ch]=vals;const orientations=[[cw-w,ch-h,'正位置'],[cw-h,ch-w,'90度回転']];const best=orientations.find(([x,y])=>x>0&&y>0)||orientations.find(([x,y])=>x>=0&&y>=0);if(!best){result.textContent='正位置・90度回転とも、どちらかの寸法が内寸を上回ります。別サイズを確認してください。';}else if(best[0]===0||best[1]===0){result.textContent=best[2]+'で同寸法の辺があります。余裕がないため、出し入れできると判断できません。';}else{result.textContent=best[2]+'で幅に'+Number(best[0].toFixed(1))+'mm、高さに'+Number(best[1].toFixed(1))+'mmの差があります。厚み・開口部と出し入れの余裕は別に確認してください。';}});}
const packInputs=[...document.querySelectorAll('[data-pack]')];
if(packInputs.length){const key='yorimichi-packing-v1';const note=document.querySelector('#pack-save');let stored={};try{stored=JSON.parse(localStorage.getItem(key)||'{}');if(!stored||typeof stored!=='object'||Array.isArray(stored))stored={};}catch{note.textContent='このブラウザでは保存できない場合があります。ページを開いている間のメモとして使えます。';}packInputs.forEach(el=>el.checked=stored[el.dataset.pack]===true);const count=()=>document.querySelector('#pack-count').textContent=packInputs.filter(el=>el.checked).length+' / '+packInputs.length+' 項目を確認';const save=()=>{count();try{localStorage.setItem(key,JSON.stringify(Object.fromEntries(packInputs.map(el=>[el.dataset.pack,el.checked]))));note.textContent='チェック状態だけを、このブラウザに保存しました。';}catch{note.textContent='このブラウザでは保存できません。ページを開いている間のメモとして使えます。';}};packInputs.forEach(el=>el.addEventListener('change',save));document.querySelector('#pack-reset').addEventListener('click',()=>{packInputs.forEach(el=>el.checked=false);count();try{localStorage.removeItem(key);note.textContent='保存したチェックを削除しました。';}catch{note.textContent='チェックを外しました。このブラウザの保存領域にはアクセスできません。';}});count();}
